    78→// syncDocuments requests document synchronization from the network.
    79→func (p *P2P) syncDocuments(
    80→	ctx context.Context,
    81→	collectionID string,
    82→	docIDs []string,
    83→) (map[string][]cid.Cid, error) {
    84→	pubsubReq := &docSyncRequest{DocIDs: docIDs}
    85→
    86→	data, err := cbor.Marshal(pubsubReq)
    87→	if err != nil {
    88→		return nil, err
    89→	}
    90→
    91→	pubSubRespChan, err := p.host.PublishToTopic(ctx, docSyncTopic, data, true)
    92→	if err != nil {
    93→		return nil, err
    94→	}
    95→
    96→	return p.waitAndHandleDocSyncResponses(ctx, collectionID, docIDs, pubSubRespChan)
    97→}
    98→
    99→// waitAndHandleDocSyncResponses handles multiple responses from different peers.
   100→func (p *P2P) waitAndHandleDocSyncResponses(
   101→	ctx context.Context,
   102→	collectionID string,
   103→	docIDs []string,
   104→	pubSubRespChan <-chan client.PubsubResponse,
   105→) (results map[string][]cid.Cid, err error) {
   106→	result := make(map[string][]cid.Cid)
   107→
   108→loop:
   109→	for {
   110→		select {
   111→		case resp := <-pubSubRespChan:
   112→			p.handleDocSyncResponse(ctx, resp, collectionID, result)
   113→
   114→			if len(result) >= len(docIDs) {
   115→				break loop
   116→			}
   117→
   118→		case <-ctx.Done():
   119→			if len(result) == 0 {
   120→				return nil, ErrTimeoutDocSync
   121→			}
   122→			break loop
   123→		}
   124→	}
   125→
   126→	return result, nil
   127→}
   128→
   129→// handleDocSyncResponse processes a single response from a peer.
   130→// It mutates the results map with the document IDs and their corresponding CIDs.
   131→func (p *P2P) handleDocSyncResponse(
   132→	ctx context.Context,
   133→	resp client.PubsubResponse,
   134→	collectionID string,
   135→	results map[string][]cid.Cid,
   136→) {
   137→	if resp.Err != nil {
   138→		log.ErrorE("Received error response from peer", resp.Err)
   139→		return
   140→	}
   141→
   142→	var reply docSyncReply
   143→	if err := cbor.Unmarshal(resp.Data, &reply); err != nil {
   144→		log.ErrorE("Failed to unmarshal doc sync reply", err)
   145→		return
   146→	}
   147→
   148→	for _, item := range reply.Results {
   149→		p.handleDocSyncItem(ctx, item, reply.Sender, collectionID, results)
   150→	}
   151→}
   152→
   153→// handleDocSyncItem handles a single document sync item from a peer response.
   154→// It mutates the results map with the document IDs and their corresponding CIDs.
   155→func (p *P2P) handleDocSyncItem(
   156→	ctx context.Context,
   157→	item docSyncItem,
   158→	senderID string,
   159→	collectionID string,
   160→	results map[string][]cid.Cid,
   161→) {
   162→	for _, headBytes := range item.Heads {
   163→		_, docCid, err := cid.CidFromBytes(headBytes)
   164→		if err != nil {
   165→			log.ErrorE("Failed to parse CID from bytes", err,
   166→				corelog.String("DocID", item.DocID))
   167→			continue
   168→		}
   169→
   170→		if heads, exists := results[item.DocID]; exists {
   171→			if !slices.Contains(heads, docCid) {
   172→				results[item.DocID] = append(heads, docCid)
   173→			} else {
   174→				// we've seen this head already, just skip
   175→				continue
   176→			}
   177→		} else {
   178→			results[item.DocID] = []cid.Cid{docCid}
   179→		}
   180→
   181→		err = p.syncDocumentAndMerge(ctx, senderID, collectionID, item.DocID, docCid)
