	"github.com/sourcenetwork/defradb/internal/db/description"
	"github.com/sourcenetwork/defradb/internal/keys"
)

func (p *P2P) FetchCollections(ctx context.Context, versionIDs ...string) error {
	linkSys := makeLinkSystem(p.host.IPLDStore())

	for _, versionID := range versionIDs {
		_, err := p.fetchCollection(ctx, versionID, linkSys)
		if err != nil {
			return err
		}
	}

	return nil
}

func (p *P2P) fetchCollection(
	ctx context.Context,
	versionID string,
	linkSys linking.LinkSystem,
) (client.CollectionVersion, error) {
	col, err := description.GetCollectionByID(ctx, versionID)
	if err != nil {
		if !errors.Is(err, corekv.ErrNotFound) {
			return client.CollectionVersion{}, err
		}
		// If it is not found, continue and try and sync it!
	} else {
		if col.IsPlaceholder {
			// If the collection is a placeholder locally, we should try and sync its proper definition
			// from across the network.
		} else {
			// If the collection exists locally, it is important to return it - this way
			// anything locally defined on it will be preserved.
			return col, nil
		}
	}

	cid, err := cid.Parse(versionID)
	if err != nil {
		return client.CollectionVersion{}, err
	}

	nd, err := linkSys.Load(linking.LinkContext{Ctx: ctx}, cidlink.Link{Cid: cid}, coreblock.BlockSchemaPrototype)
	if err != nil {
		return client.CollectionVersion{}, err
	}

	linkBlock, err := coreblock.GetFromNode(nd)
	if err != nil {
		return client.CollectionVersion{}, err
	}

	var collectionID string
	var previous immutable.Option[client.CollectionSource]
	if len(linkBlock.Heads) == 1 {
		// There can only ever be one or zero heads for a collection version.
		// If there is one, this must be an new version of a collection and
		// we need to sync the older version(s) recursively.
		previousID := linkBlock.Heads[0].String()
		col, err = p.fetchCollection(ctx, previousID, linkSys)
		if err != nil {
			return client.CollectionVersion{}, err
		}

		previous = immutable.Some(
			client.CollectionSource{
				SourceCollectionID: previousID,
			},
		)
		collectionID = col.CollectionID
	}

	fields := make([]client.CollectionFieldDescription, 0, len(col.Fields))
	fields = append(fields, col.Fields...)

	if len(fields) == 0 && len(linkBlock.Links) > 0 {
		// Ensure the length is at least one, if this is the first time receiving fields for this
		// node/collection, the first field *must* be the docID field.
		fields = make([]client.CollectionFieldDescription, 1, len(linkBlock.Links))
	}

	for _, fieldCid := range linkBlock.Links {
		fieldNode, err := linkSys.Load(linking.LinkContext{Ctx: ctx}, fieldCid, coreblock.BlockSchemaPrototype)
		if err != nil {
			return client.CollectionVersion{}, err
		}

		fieldLinkBlock, err := coreblock.GetFromNode(fieldNode)
		if err != nil {
			return client.CollectionVersion{}, err
		}

		fieldDelta := fieldLinkBlock.Delta.FieldDefinitionDelta

		// WARNING - At the moment fields can only ever be added, the following code relies on this.
		// When we allow the mutation of fields, this code will need to change.
		var kind client.FieldKind
		if fieldDelta.RelativeID != nil {
			kind = &client.SelfKind{
				RelativeID: strconv.Itoa(*fieldDelta.RelativeID),
				// The secondary side of SelfKind relationships are never represented by
				// blocks, so we can safely hardcode this to `false`
				Array: false,
			}
		} else if fieldDelta.CollectionID != nil {
			kind = &client.CollectionKind{
				CollectionID: *fieldDelta.CollectionID,
				// The secondary side of CollectionKind relationships are never represented by
				// blocks, so we can safely hardcode this to `false`
				Array: false,
			}
		} else {
			kind = client.IntToFieldKind(*fieldDelta.ScalarKind)
		}

		field := client.CollectionFieldDescription{
			FieldID: fieldCid.String(),
			Name:    *fieldDelta.Name,
			Typ:     *fieldDelta.Crdt,
			Kind:    kind,
		}

		if *fieldDelta.Name == request.DocIDFieldName {
			// The first field *must* be the doc id field - this is a largely a cosmetic
			// decision, however by now some code does rely on this.
			fields[0] = field
		} else {
			fields = append(
				fields,
				field,
			)
		}
	}

	var query immutable.Option[client.QuerySource]
	if linkBlock.Delta.CollectionDefinitionDelta.QuerySelect != nil {
		var q request.Select
		err = json.Unmarshal(linkBlock.Delta.CollectionDefinitionDelta.QuerySelect, &q)
		if err != nil {
			return client.CollectionVersion{}, err
		}

		var transform immutable.Option[string]
		if linkBlock.Delta.CollectionDefinitionDelta.QueryTransform != nil {
			err = p.lens.P2P.Value().SyncLens(ctx, linkBlock.Delta.CollectionDefinitionDelta.QueryTransform.String())
			if err != nil {
				return client.CollectionVersion{}, err
			}

			transform = immutable.Some(linkBlock.Delta.CollectionDefinitionDelta.QueryTransform.String())
		}

		query = immutable.Some(client.QuerySource{
			Query:     q,
			Transform: transform,
		})
	}

	// Merge the details taken from this block onto the previous

	if len(collectionID) > 0 && collectionID != client.OrphanCollectionID {
		col.CollectionID = collectionID
	} else {
		col.CollectionID = versionID
	}

	col.VersionID = versionID
	col.PreviousVersion = previous
	col.Query = query
	col.Fields = fields
	// Ensure that this newly received version is inactive, and that we have not copied
	// IsActive from a locally known version.
	col.IsActive = false

	if linkBlock.Delta.CollectionDefinitionDelta.Name != nil {
		col.Name = *linkBlock.Delta.CollectionDefinitionDelta.Name
	}

	// Non-views must be materialized.  Views are synced as non-materialized - users
	// can toggle this locally if they like.
	col.IsMaterialized = !query.HasValue()

	err = description.SaveCollection(ctx, col)
	if err != nil {
		return client.CollectionVersion{}, err
	}

	return col, nil
}

// collectionSyncTopic is the fixed topic for branchable collection sync operations.
const collectionSyncTopic = "collection-sync"

// collectionSyncRequest represents a request to synchronize a branchable collection.
type collectionSyncRequest struct {
	CollectionName string `json:"collectionName"`
}

// collectionSyncReply represents the response to a collection sync request.
type collectionSyncReply struct {
	CollectionName string   `json:"collectionName"`
	Head           []byte   `json:"head"` // CID bytes of the collection head
	Sender         string   `json:"sender"`
}

// SyncBranchableCollection initiates a request for the latest version of the branchable
// collection's DAG from the network.
//
// This function call will block until there is a response for the collection.
// It is the responsibility of the caller to set an appropriate timeout on the context.
func (p *P2P) SyncBranchableCollection(ctx context.Context, collectionName string) error {
	cols, err := p.db.GetCollections(
		ctx,
		client.CollectionFetchOptions{
			Name: immutable.Some(collectionName),
		},
	)
	if err != nil {
		return err
	}
	if len(cols) == 0 {
		return client.NewErrCollectionNotFoundForName(collectionName)
	}

	col := cols[0].Version()
	if !col.IsBranchable {
		return errors.New("collection is not branchable", errors.NewKV("Name", collectionName))
	}

	collectionID := col.CollectionID
	_, err = p.syncBranchableCollection(ctx, collectionName, collectionID)
	return err
}

// syncBranchableCollection requests branchable collection synchronization from the network.
func (p *P2P) syncBranchableCollection(
	ctx context.Context,
	collectionName string,
	collectionID string,
) (cid.Cid, error) {
	pubsubReq := &collectionSyncRequest{CollectionName: collectionName}

	data, err := cbor.Marshal(pubsubReq)
	if err != nil {
		return cid.Undef, err
	}

	pubSubRespChan, err := p.host.PublishToTopic(ctx, collectionSyncTopic, data, true)
	if err != nil {
		return cid.Undef, err
	}

	return p.waitAndHandleCollectionSyncResponse(ctx, collectionID, collectionName, pubSubRespChan)
}

// waitAndHandleCollectionSyncResponse handles the response from a peer.
func (p *P2P) waitAndHandleCollectionSyncResponse(
	ctx context.Context,
	collectionID string,
	collectionName string,
	pubSubRespChan <-chan client.PubsubResponse,
) (cid.Cid, error) {
	select {
	case resp := <-pubSubRespChan:
		return p.handleCollectionSyncResponse(ctx, resp, collectionID, collectionName)

	case <-ctx.Done():
		return cid.Undef, ErrTimeoutCollectionSync
	}
}

// handleCollectionSyncResponse processes a single response from a peer.
func (p *P2P) handleCollectionSyncResponse(
	ctx context.Context,
	resp client.PubsubResponse,
	collectionID string,
	collectionName string,
) (cid.Cid, error) {
	if resp.Err != nil {
		return cid.Undef, resp.Err
	}

	var reply collectionSyncReply
	if err := cbor.Unmarshal(resp.Data, &reply); err != nil {
		return cid.Undef, err
	}

	if reply.CollectionName != collectionName {
		return cid.Undef, errors.New("received response for different collection",
			errors.NewKV("Expected", collectionName),
			errors.NewKV("Received", reply.CollectionName))
	}

	if len(reply.Head) == 0 {
		// Peer doesn't have this collection or it has no commits yet
		return cid.Undef, errors.New("peer has no commits for collection",
			errors.NewKV("Name", collectionName))
	}

	_, colCid, err := cid.CidFromBytes(reply.Head)
	if err != nil {
		return cid.Undef, err
	}

	err = p.syncCollectionAndMerge(ctx, reply.Sender, collectionID, collectionName, colCid)
	if err != nil {
		return cid.Undef, err
	}

	return colCid, nil
}

// syncCollectionAndMerge synchronizes a branchable collection from a remote peer and publishes a merge event.
func (p *P2P) syncCollectionAndMerge(
	ctx context.Context,
	senderID string,
	collectionID string,
	collectionName string,
	head cid.Cid,
) error {
	err := p.syncCollectionDAG(ctx, head)
	if err != nil {
		return err
	}

	evt := event.Merge{
		ByPeer:       senderID,
		FromPeer:     p.host.ID(),
		Cid:          head,
		CollectionID: collectionID,
	}

	return p.db.Merge(ctx, evt)
}

// syncCollectionDAG synchronizes the DAG for a specific branchable collection CID.
func (p *P2P) syncCollectionDAG(ctx context.Context, colCid cid.Cid) error {
	linkSys := makeLinkSystem(p.host.IPLDStore())

	nd, err := linkSys.Load(linking.LinkContext{Ctx: ctx}, cidlink.Link{Cid: colCid}, coreblock.BlockSchemaPrototype)
	if err != nil {
		return err
	}

	linkBlock, err := coreblock.GetFromNode(nd)
	if err != nil {
		return err
	}

	return p.syncDAG(ctx, linkBlock)
}

// collectionSyncMessageHandler handles incoming branchable collection sync requests from the pubsub network.
func (p *P2P) collectionSyncMessageHandler(from string, topic string, msg []byte) ([]byte, error) {
	req := &collectionSyncRequest{}
	if err := cbor.Unmarshal(msg, req); err != nil {
		return nil, err
	}

	head, err := p.processCollectionSyncItem(req.CollectionName)
	if err != nil {
		// Return empty head if collection not found or not branchable
		head = []byte{}
	}

	reply := &collectionSyncReply{
		Sender:         p.host.ID(),
		CollectionName: req.CollectionName,
		Head:           head,
	}

	return cbor.Marshal(reply)
}

// processCollectionSyncItem processes a branchable collection sync request and returns the head CID.
func (p *P2P) processCollectionSyncItem(collectionName string) ([]byte, error) {
	clientTxn, err := p.db.NewTxn(true)
	if err != nil {
		return nil, err
	}
	defer clientTxn.Discard()

	cols, err := p.db.GetCollections(
		p.ctx,
		client.CollectionFetchOptions{
			Name: immutable.Some(collectionName),
		},
	)
	if err != nil || len(cols) == 0 {
		return nil, err
	}

	col := cols[0].Version()
	if !col.IsBranchable {
		return nil, errors.New("collection is not branchable", errors.NewKV("Name", collectionName))
	}

	// Get the collection head from headstore
	txn := datastore.MustGetFromClientTxn(clientTxn)

	shortID, err := dbid.GetShortCollectionID(p.ctx, col.CollectionID)
	if err != nil {
		return nil, err
	}

	key := keys.NewHeadstoreColKey(shortID)
	headset := coreblock.NewHeadSet(txn.Headstore(), key)

	cids, _, err := headset.List(p.ctx)
	if err != nil {
		return nil, err
	}

	if len(cids) == 0 {
		return nil, errors.New("no heads found for branchable collection", errors.NewKV("Name", collectionName))
	}

	// Return the first (and should be only) head
	return cids[0].Bytes(), nil
}

