	if err != nil {
		return []client.CollectionVersion{}, err
	}

	callHandle := getNodeOrTxnHandle(w.handle, ctx)
	res := ConvertAndFreeCResult(C.ViewAdd(callHandle, cQuery, cSDL, cTransform))

	if res.Status != 0 {
