	}

	handle := cgo.Handle(res.txnPtr)
	clientTxn := handle.Value().(client.Txn) //nolint:forcetypeassert
	retTxn := &Transaction{w, clientTxn, handle}
	txnHandleMap.Store(retTxn, handle)

	return retTxn, nil
}

