func TestBranchableCollectionSync_WithSimpleBranchableCollection_ShouldSyncCommits(t *testing.T) {
	test := testUtils.TestCase{
		Actions: []any{
			testUtils.RandomNetworkingConfig(),
			testUtils.RandomNetworkingConfig(),
			// Add schema to both nodes
			&action.AddSchema{
				NodeID: immutable.Some(0),
				Schema: `
					type Users @branchable {
						name: String
					}
				`,
			},
			&action.AddSchema{
				NodeID: immutable.Some(1),
				Schema: `
					type Users @branchable {
						name: String
					}
				`,
			},
			// Create document on node 0
			testUtils.CreateDoc{
				NodeID: immutable.Some(0),
				Doc: `{
					"name": "John"
				}`,
			},
			testUtils.ConnectPeers{
				SourceNodeID: 0,
				TargetNodeID: 1,
			},
			testUtils.SubscribeToCollection{
				NodeID:        1,
				CollectionIDs: []int{0},
			},
			// Sync the branchable collection's DAG from node 0 to node 1
			&action.SyncBranchableCollection{
				NodeID:         1,
				CollectionName: "Users",
			},
			testUtils.WaitForSync{},
			// Verify collection commits exist on node 1
			testUtils.Request{
				NodeID: immutable.Some(1),
				Request: `query {
					_commits(collectionID: "{{.CollectionID0}}") {
						cid
					}
				}`,
				Results: map[string]any{
					"_commits": []map[string]any{
						{
							"cid": "{{.AnyString}}",
						},
					},
				},
			},
		},
	}

	testUtils.ExecuteTestCase(t, test)
}

