    96→
    97→// waitAndHandleCollectionSyncResponse handles the response from a peer.
    98→func (p *P2P) waitAndHandleCollectionSyncResponse(
    99→	ctx context.Context,
   100→	collectionID string,
   101→	collectionName string,
   102→	pubSubRespChan <-chan client.PubsubResponse,
   103→) (cid.Cid, error) {
