   112→
   113→// handleCollectionSyncResponse processes a single response from a peer.
   114→func (p *P2P) handleCollectionSyncResponse(
   115→	ctx context.Context,
   116→	resp client.PubsubResponse,
   117→	collectionID string,
   118→	collectionName string,
   119→) (cid.Cid, error) {
   120→	if resp.Err != nil {
   121→		return cid.Undef, resp.Err
   122→	}
   123→
