   132→			errors.NewKV("Received", reply.CollectionName))
   133→	}
   134→
   135→	if len(reply.Head) == 0 {
   136→		return cid.Undef, errors.New("peer has no commits for collection",
   137→			errors.NewKV("Name", collectionName))
