	getPeerCollections.OperationID = "peer_collections_list"
	getPeerCollections.Tags = []string{"p2p"}
	getPeerCollections.AddResponse(200, getPeerCollectionsResponse)
	getPeerCollections.Responses.Set("400", errorResponse)

